//! R01 request permission remains independent of retired accounting.
use workbench_host::workflow::{import,spend,state::{ProjectState,ProjectBudget,BudgetPolicy,SpendRequestMetadata,JobRecord}};
use workbench_host::voice_spend;
use std::path::Path;
use std::sync::atomic::{AtomicUsize,Ordering};
fn request(ch:char)->SpendRequestMetadata{SpendRequestMetadata{request_hash:ch.to_string().repeat(64),disclosure:None,duration_seconds:None,width:None,height:None,prediction_id:None}}
fn setup(policy:BudgetPolicy)->tempfile::TempDir{let dir=tempfile::tempdir().unwrap();let mut s=ProjectState::new();s.budget=Some(ProjectBudget{currency:"EUR".into(),limit_minor:Some(0),hard_stop:true,policy:Some(policy),..Default::default()});let mut old=JobRecord::open("legacy-history","old-operation");old.provider=Some("old-provider".into());old.cost_minor=Some(25);old.estimated_cost_minor=Some(30);old.finish(None,None);s.jobs.push(old);import::persist_state(dir.path(),&s).unwrap();dir}
fn token(root:&Path,hash:&str)->String{let q=spend::quote_unbounded_scoped(root,hash).unwrap();spend::confirm_unbounded_scoped(root,"unpriced-provider","media","generate","test-model",hash,&q.ledger_revision).unwrap()}
fn run(root:&Path,req:SpendRequestMetadata,t:Option<&str>,f:impl FnOnce()->Result<String,String>)->Result<String,String>{spend::run_scoped_with_request(root,"unpriced-provider","media","generate","unknown.capability","test-model",t,None,Some(req),None,f)}
#[test]
fn r01_every_legacy_budget_is_inert_but_each_operation_requires_permission(){for policy in [BudgetPolicy::StrictHardStop,BudgetPolicy::ApprovalRequired,BudgetPolicy::WarnOnly]{let d=setup(policy);let before=import::load_state(d.path()).unwrap();let calls=AtomicUsize::new(0);for ch in ['a','b']{let req=request(ch);assert!(run(d.path(),req.clone(),None,||panic!("no approval dispatched")).is_err());let t=token(d.path(),&req.request_hash);assert_eq!(run(d.path(),req.clone(),Some(&t),||{calls.fetch_add(1,Ordering::Relaxed);Ok("done".into())}).unwrap(),"done");assert!(run(d.path(),req,Some(&t),||panic!("duplicate dispatch")).is_err());}assert_eq!(calls.load(Ordering::Relaxed),2);let after=import::load_state(d.path()).unwrap();assert_eq!(serde_json::to_value(&before.budget).unwrap(),serde_json::to_value(&after.budget).unwrap());assert_eq!(serde_json::to_value(&before.jobs[0]).unwrap(),serde_json::to_value(&after.jobs[0]).unwrap());for j in &after.jobs[1..]{assert!(j.cost_minor.is_none()&&j.estimated_cost_minor.is_none()&&j.reserved_max_minor.is_none());}}}
#[test]
fn r01_permission_bound_to_exact_payload_provider_model_and_project(){let d=setup(BudgetPolicy::StrictHardStop);let req=request('c');let t=token(d.path(),&req.request_hash);let other=setup(BudgetPolicy::StrictHardStop);assert!(run(other.path(),req.clone(),Some(&t),||panic!("cross project")).is_err());assert!(run(d.path(),request('d'),Some(&t),||panic!("changed payload")).is_err());for(provider,model)in [("other-provider","test-model"),("unpriced-provider","other-model")]{assert!(spend::run_scoped_with_request(d.path(),provider,"media","generate","unknown.capability",model,Some(&t),None,Some(req.clone()),None,||panic!("changed route")).is_err());}assert_eq!(run(d.path(),req,Some(&t),||Ok("bound".into())).unwrap(),"bound");}
#[test]
fn r01_prediction_is_durable_before_polling_and_uncertain_attempt_cannot_replay(){let d=setup(BudgetPolicy::StrictHardStop);let req=request('e');let t=token(d.path(),&req.request_hash);let result=spend::run_scoped_with_submission(d.path(),"unpriced-provider","media","generate","unknown.capability","test-model",Some(&t),None,Some(req.clone()),None,|id,submitted|{submitted("r01-prediction-original")?;assert_eq!(spend::recovery_job(d.path(),id).unwrap(),("unpriced-provider".into(),"r01-prediction-original".into()));Err("fixture polling failure".into())});assert!(result.unwrap_err().contains("polling failure"));let after=import::load_state(d.path()).unwrap();let j=after.jobs.last().unwrap();assert_eq!(spend::recovery_job(d.path(),&j.id).unwrap().1,"r01-prediction-original");let fresh=token(d.path(),&req.request_hash);assert!(run(d.path(),req,Some(&fresh),||panic!("uncertain resubmission")).is_err());}
#[test]
fn r01_legacy_manual_accounting_does_not_make_provider_resubmission_safe(){let d=setup(BudgetPolicy::StrictHardStop);let req=request('f');let t=token(d.path(),&req.request_hash);assert!(run(d.path(),req.clone(),Some(&t),||Err("network uncertain".into())).is_err());let mut s=import::load_state(d.path()).unwrap();let j=s.jobs.last_mut().unwrap();j.cost_minor=Some(0);j.actual_verified=false;import::persist_state(d.path(),&s).unwrap();let fresh=token(d.path(),&req.request_hash);assert!(run(d.path(),req,Some(&fresh),||panic!("numeric history authorized replay")).is_err());}
#[test]
fn r01_voice_legacy_strict_budget_needs_permission_not_ceiling_or_price(){let d=setup(BudgetPolicy::StrictHardStop);let op="elevenlabs_tts_preview";let model="eleven_multilingual_v2";let input=r#"{"text":"R01 local voice fixture","voice_id":"fixture-voice"}"#;let q=voice_spend::quote(d.path(),op,model,input).unwrap();assert!(voice_spend::run(d.path(),op,model,input,None,||panic!("unapproved voice")).is_err());let t=voice_spend::confirm_unbounded(d.path(),op,model,input,&q.request_hash,q.ledger_revision.as_deref().unwrap()).unwrap();assert_eq!(voice_spend::run(d.path(),op,model,input,Some(&t),||Ok("local-voice-result".into())).unwrap(),"local-voice-result");assert!(voice_spend::run(d.path(),op,model,input,Some(&t),||panic!("voice replay")).is_err());let s=import::load_state(d.path()).unwrap();let j=s.jobs.last().unwrap();assert!(j.cost_minor.is_none()&&j.estimated_cost_minor.is_none()&&j.reserved_max_minor.is_none());}
#[test]
fn r01_missing_or_corrupt_state_fails_closed(){let d=tempfile::tempdir().unwrap();assert!(spend::quote_unbounded_scoped(d.path(),&request('a').request_hash).is_err());std::fs::create_dir_all(d.path().join("Preproduction")).unwrap();std::fs::write(d.path().join("Preproduction/workflow_state.json"),b"{broken").unwrap();assert!(run(d.path(),request('a'),Some("fake"),||panic!("corrupt state dispatched")).is_err());}
